// Pure business rules. No network, no MCP. This file is ALSO embedded (by scripts/build-workflow.js) into an
// n8n Code node, so the digest workflow and the MCP server apply exactly the same definition of "stale".
//
// DEFINITION: a deal is STALE when it is open, has no scheduled next step (no undone activity), and nothing
// has touched it (update, stage change, or creation) for at least N days.
// Caveat: Pipedrive's `update_time` may not move when a note or email is added, so treat "stale" as
// "worth a look", not proof of neglect.

const DAY_MS = 24 * 60 * 60 * 1000;

function parseTime(value) {
  if (!value) return null;
  let s = String(value);
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(s)) s = s.replace(' ', 'T') + 'Z'; // v1-style timestamps are UTC
  const t = Date.parse(s);
  return Number.isNaN(t) ? null : t;
}

function lastTouchedMs(deal) {
  const times = [deal.update_time, deal.stage_change_time, deal.add_time].map(parseTime).filter((t) => t !== null);
  return times.length ? Math.max(...times) : null;
}

function daysIdle(deal, nowMs) {
  const t = lastTouchedMs(deal);
  if (t === null) return null; // unknown: never guess
  return Math.max(0, Math.floor((nowMs - t) / DAY_MS));
}

function hasScheduledNext(deal) {
  return Number(deal.undone_activities_count) > 0 || (deal.next_activity_id !== null && deal.next_activity_id !== undefined);
}

function isStale(deal, nowMs, days) {
  if (deal.status !== 'open') return false;
  if (hasScheduledNext(deal)) return false;
  const idle = daysIdle(deal, nowMs);
  return idle !== null && idle >= days;
}

function compactDeal(deal, nowMs) {
  return {
    id: deal.id,
    title: deal.title,
    value: deal.value,
    currency: deal.currency,
    stage_id: deal.stage_id,
    owner_id: deal.owner_id,
    days_idle: daysIdle(deal, nowMs),
    has_next_activity: hasScheduledNext(deal),
  };
}

const round2 = (n) => Math.round(n * 100) / 100;

// Single source of truth for the numbers in a digest. Used by the MCP tools AND the n8n reconciliation step.
function computeFacts(deals, nowMs, staleDays) {
  const open = deals.filter((d) => d.status === 'open');
  const staleDeals = open
    .filter((d) => isStale(d, nowMs, staleDays))
    .map((d) => compactDeal(d, nowMs))
    .sort((a, b) => b.days_idle - a.days_idle || a.id - b.id);
  const valueByCurrency = {};
  for (const d of open) {
    const cur = d.currency || 'UNKNOWN';
    valueByCurrency[cur] = round2((valueByCurrency[cur] || 0) + (Number(d.value) || 0));
  }
  const titles = {};
  for (const d of open) titles[d.id] = d.title;
  return {
    stale_days: staleDays,
    open_count: open.length,
    open_ids: open.map((d) => d.id).sort((a, b) => a - b),
    value_by_currency: valueByCurrency,
    stale_count: staleDeals.length,
    stale_ids: staleDeals.map((d) => d.id).sort((a, b) => a - b),
    stale: staleDeals,
    titles,
  };
}

function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Notes come from outside (callers, colleagues, other automations). Strip markup and cap length before an LLM sees them.
function stripHtml(s, maxLen = 300) {
  const text = String(s == null ? '' : s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim();
  return text.length > maxLen ? text.slice(0, maxLen - 1) + '…' : text;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { DAY_MS, parseTime, lastTouchedMs, daysIdle, hasScheduledNext, isStale, compactDeal, computeFacts, escapeHtml, stripHtml };
}


// ---- n8n glue for node "Compute Facts" (domain.js above is embedded verbatim) ----
if (typeof $input !== 'undefined') {
  const cfg = $('Config').first().json;
  const resp = $input.first().json;
  if (!resp || resp.success !== true || !Array.isArray(resp.data)) {
    throw new Error('Unexpected Pipedrive response while fetching open deals');
  }
  if (resp.additional_data && resp.additional_data.next_cursor) {
    throw new Error('More than 500 open deals: this workflow does not page the ground-truth fetch yet, so it cannot verify the digest');
  }
  const staleDays = Number(cfg.staleDays);
  if (!Number.isInteger(staleDays) || staleDays < 1) throw new Error('Config.staleDays must be a whole number >= 1');
  return [{ json: computeFacts(resp.data, Date.now(), staleDays) }];
}

// Embedded (by scripts/build-workflow.js) into the n8n "Reconcile" Code node.
// The agent's digest is checked against numbers computed by plain code from Pipedrive data, BEFORE anything is
// posted. If they disagree, the digest is withheld and a human is told. Posted numbers always come from the facts,
// never from the model's text.

function extractJson(raw) {
  const s = String(raw == null ? '' : raw);
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start === -1 || end <= start) throw new Error('Agent did not return a JSON object');
  return JSON.parse(s.slice(start, end + 1));
}

const isIntArray = (a) => Array.isArray(a) && a.every((n) => Number.isInteger(n));

function reconcile(agent, facts) {
  const problems = [];
  if (!agent || typeof agent !== 'object') return { ok: false, problems: ['Agent output is not an object'] };

  if (agent.open_deals_count !== facts.open_count) {
    problems.push(`open_deals_count: agent said ${agent.open_deals_count}, Pipedrive data says ${facts.open_count}`);
  }
  if (agent.stale_deals_count !== facts.stale_count) {
    problems.push(`stale_deals_count: agent said ${agent.stale_deals_count}, Pipedrive data says ${facts.stale_count}`);
  }
  if (!isIntArray(agent.stale_deal_ids)) {
    problems.push('stale_deal_ids is missing or not a list of integers');
  } else {
    const a = [...agent.stale_deal_ids].sort((x, y) => x - y).join(',');
    const f = [...facts.stale_ids].sort((x, y) => x - y).join(',');
    if (a !== f) problems.push(`stale_deal_ids differ: agent [${a}] vs data [${f}]`);
  }
  const openSet = new Set(facts.open_ids);
  for (const fu of Array.isArray(agent.follow_ups) ? agent.follow_ups : []) {
    if (!fu || !openSet.has(fu.deal_id)) problems.push(`follow_up references deal ${fu && fu.deal_id}, which is not an open deal`);
  }
  if (typeof agent.headline !== 'string' || !agent.headline.trim()) problems.push('headline is missing');
  return { ok: problems.length === 0, problems };
}

// The agent's text is influenced by CRM content someone else wrote. Never let it ping a channel or inject Slack links.
function sanitizeForSlack(s, maxLen) {
  return String(s == null ? '' : s)
    .replace(/<[^>]*>/g, ' ')          // drops HTML tags AND Slack syntax such as <!channel>, <@U123>, <http://x|label>
    .replace(/[<>]/g, '')               // any stray brackets
    .replace(/@(channel|here|everyone)\b/gi, '$1')
    .replace(/\s+/g, ' ').trim()
    .slice(0, maxLen);
}

function money(n) {
  const [whole, frac] = Number(n).toFixed(2).split('.');
  return whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + '.' + frac;
}

function buildDigestText(agent, facts, whenLabel) {
  const values = Object.entries(facts.value_by_currency).map(([cur, v]) => `${cur} ${money(v)}`).join(', ') || 'n/a';
  const lines = [];
  lines.push(`*Daily ops digest* (${whenLabel})`);
  lines.push(sanitizeForSlack(agent.headline, 200));
  lines.push(`Open deals: *${facts.open_count}* (${values}) | Stale (no next step, idle ${facts.stale_days}+ days): *${facts.stale_count}*`);
  if (facts.stale.length) {
    lines.push('*Stale deals*');
    for (const d of facts.stale.slice(0, 10)) {
      lines.push(`- #${d.id} ${sanitizeForSlack(facts.titles[d.id], 90)} (idle ${d.days_idle}d)`);
    }
    if (facts.stale.length > 10) lines.push(`...and ${facts.stale.length - 10} more`);
  }
  const followUps = (Array.isArray(agent.follow_ups) ? agent.follow_ups : []).slice(0, 5);
  if (followUps.length) {
    lines.push('*Suggested follow-ups*');
    for (const fu of followUps) lines.push(`- #${fu.deal_id} ${sanitizeForSlack(facts.titles[fu.deal_id], 60)}: ${sanitizeForSlack(fu.action, 160)}`);
  }
  lines.push('_Counts verified against Pipedrive data before posting._');
  return lines.join('\n');
}

if (typeof module !== 'undefined' && module.exports) module.exports = { extractJson, reconcile, sanitizeForSlack, buildDigestText, money };


// ---- n8n glue for node "Reconcile" (reconcile.js above is embedded verbatim) ----
if (typeof $input !== 'undefined') {
  const facts = $('Compute Facts').first().json;
  const raw = $input.first().json.output; // text produced by the AI Agent node
  let agent = null;
  let parseError = null;
  try { agent = extractJson(raw); } catch (e) { parseError = e.message; }

  const result = parseError
    ? { ok: false, problems: ['Could not parse agent output: ' + parseError] }
    : reconcile(agent, facts);

  const whenLabel = new Date().toLocaleDateString('en-AU', { timeZone: 'Australia/Melbourne', weekday: 'short', day: 'numeric', month: 'short' });
  return [{
    json: {
      ok: result.ok,
      problems: result.problems,
      text: result.ok ? buildDigestText(agent, facts, whenLabel) : null,
      agent_raw: String(raw == null ? '' : raw).slice(0, 1500),
      facts_summary: { open: facts.open_count, stale: facts.stale_count, stale_ids: facts.stale_ids },
    },
  }];
}
